    font-family: 'Pacifico';
    src: url('../../../../fonts/Pacifico/Pacifico-Regular.ttf');
    font-weight: 400;
}
@font-face {
    font-family: 'Bebas';
    src: url('../../../../fonts/Bebas/Bebas-Regular.otf'),
         url('../../../../fonts/Bebas/Bebas-Regular.ttf');
    font-weight: 400;
}
