    font-family: 'Roboto';
    src: url('../../../../fonts/Roboto/Roboto-Medium.ttf');
    font-weight: 500;
}
@font-face {
    font-family: 'Roboto';
    src: url('../../../../fonts/Roboto/Roboto-Regular.ttf');
    font-weight: 400;
}
@font-face {
    font-family: 'Roboto';
    src: url('../../../../fonts/Roboto/Roboto-RegularItalic.ttf');
    font-weight: 400;
}

* {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
}

header,main,.footer {
    max-width: 960px;
    margin: 0 auto;
    padding: 0 10px;
}

@media screen and (max-width: 481px) {

    body {
        min-width: 320px;
    }
}

